using System.Threading.Tasks;
using FlowableWrapper.Api.Filters;
using FlowableWrapper.Application.Dtos;
using FlowableWrapper.Application.Services;
using FlowableWrapper.Infrastructure.Reliability;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;

namespace FlowableWrapper.Api.Controllers
{
    /// <summary>
    /// 流程生命周期接口
    /// </summary>
    [ApiController]
    [Route("api/processes")]
    public class ProcessController : ControllerBase
    {
        private readonly ProcessLifecycleAppService _lifecycleService;
        private readonly ILogger<ProcessController> _logger;
        private readonly OperationConcurrencyGate _concurrencyGate;

        public ProcessController(
            ProcessLifecycleAppService lifecycleService,
            OperationConcurrencyGate concurrencyGate,
            ILogger<ProcessController> logger)
        {
            _lifecycleService = lifecycleService;
            _concurrencyGate   = concurrencyGate;
            _logger           = logger;
        }

        /// <summary>
        /// 启动流程
        /// POST /api/processes/start
        ///
        /// 调用示例：
        /// {
        ///   "businessType": "personnel_selection_approval",
        ///   "businessId": "SELECTION_2024_001",
        ///   "initialSlotSelections": [
        ///     { "slotKey": "group_leader", "users": ["EMP_001"] }
        ///   ],
        ///   "businessVariables": { "title": "2024年第一批选调" },
        ///   "callback": { "url": "https://biz-system/api/workflow/callback" }
        /// }
        /// </summary>
        [HttpPost("start")]
        public async Task<ActionResult<ApiResult<StartProcessResponse>>> StartProcess(
            [FromBody] StartProcessRequest request)
        {
            using var lease = await _concurrencyGate.EnterProcessStartAsync(
                HttpContext.RequestAborted);
            var result = await _lifecycleService.StartProcessAsync(request);
            return Ok(ApiResult<StartProcessResponse>.Ok(result));
        }

        /// <summary>
        /// 终止流程（管理员操作）
        /// POST /api/processes/terminate
        /// </summary>
        [HttpPost("terminate")]
        public async Task<ActionResult<ApiResult<object>>> TerminateProcess(
            [FromBody] TerminateProcessRequest request)
        {
            await _lifecycleService.TerminateProcessAsync(request);
            return Ok(ApiResult.OkEmpty("流程已终止"));
        }
    }
}

using System;
using System.Threading.Tasks;
using FlowableWrapper.Api.Filters;
using FlowableWrapper.Application.Dtos;
using FlowableWrapper.Application.Services;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;

namespace FlowableWrapper.Api.Controllers
{
    /// <summary>
    /// Flowable HTTP Task 回调接收接口
    ///
    /// 此接口仅由 Flowable 引擎调用，不由业务系统或前端直接调用。
    /// URL 配置：appsettings.json → Flowable.FrameworkCallbackUrl
    ///
    /// Flowable HTTP Task 重试行为：
    ///   2xx  → 成功，Flowable 流程正常结束
    ///   5xx  → 失败，Flowable 触发重试（按 BPMN HTTP Task 配置的重试次数）
    ///   超限 → 进 Flowable 死信队列，运维人工处理
    ///
    /// ⚠ 注意：此 Controller 不使用 GlobalExceptionFilter 的 400 转换
    ///         所有异常必须返回 5xx，否则 Flowable 不会触发重试
    /// </summary>
    [ApiController]
    [Route("api/callback")]
    public class CallbackController : ControllerBase
    {
        private readonly ProcessCallbackAppService _callbackService;
        private readonly ILogger<CallbackController> _logger;

        public CallbackController(
            ProcessCallbackAppService callbackService,
            ILogger<CallbackController> logger)
        {
            _callbackService = callbackService;
            _logger          = logger;
        }

        /// <summary>
        /// 接收 Flowable HTTP Task 回调
        /// POST /api/callback/flowable
        ///
        /// BPMN 中 HTTP Task 配置参考：
        ///   requestMethod  : POST
        ///   requestUrl     : ${frameworkCallbackUrl}
        ///   requestHeaders : Content-Type: application/json
        ///   requestBody    : {
        ///                      "processInstanceId":"${execution.processInstanceId}",
        ///                      "businessId":"${businessId}",
        ///                      "processDefinitionKey":"${processDefinitionKey}"
        ///                    }
        /// </summary>
        [AllowAnonymous]
        [HttpPost("flowable")]
        public async Task<ActionResult<FlowableCallbackResponse>> HandleFlowableCallback(
            [FromBody] FlowableCallbackRequest request)
        {
            try
            {
                var result = await _callbackService.HandleFlowableCallbackAsync(request);

                // 返回 200：Flowable 认为回调处理成功，流程正常结束
                return Ok(result);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex,
                    "Flowable 回调处理失败，返回 500 触发 Flowable 重试: " +
                    "ProcessInstanceId={ProcessInstanceId}",
                    request?.ProcessInstanceId);

                // 返回 500：触发 Flowable HTTP Task 重试机制
                // ⚠ 不能返回 400（Flowable 认为客户端错误，不重试）
                return StatusCode(500, new FlowableCallbackResponse
                {
                    Success = false,
                    Message = ex.Message
                });
            }
        }
    }
}

using System.Collections.Generic;
using System.Threading.Tasks;
using FlowableWrapper.Api.Filters;
using FlowableWrapper.Application.Dtos;
using FlowableWrapper.Application.Services;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;

namespace FlowableWrapper.Api.Controllers
{
    /// <summary>
    /// 流程查询接口（只读）
    /// </summary>
    [ApiController]
    [Route("api/processes")]
    public class ProcessQueryController : ControllerBase
    {
        private readonly ProcessQueryAppService _queryService;
        private readonly ILogger<ProcessQueryController> _logger;

        public ProcessQueryController(
            ProcessQueryAppService queryService,
            ILogger<ProcessQueryController> logger)
        {
            _queryService = queryService;
            _logger       = logger;
        }

        /// <summary>
        /// 查询流程进度（含当前节点 + 审批历史）
        /// GET /api/processes/{businessId}/progress
        ///
        /// 数据来源：
        ///   基本信息    → ES ProcessMetadataDocument
        ///   当前节点    → Flowable 实时查询
        ///   审批历史    → ES ProcessAuditRecord
        ///
        /// 流程已结束时 currentNodes 为空列表
        /// </summary>
        [HttpGet("{businessId}/progress")]
        public async Task<ActionResult<ApiResult<ProcessProgressDto>>> GetProgress(
            string businessId)
        {
            var result = await _queryService.GetProcessProgressAsync(businessId);
            return Ok(ApiResult<ProcessProgressDto>.Ok(result));
        }

        /// <summary>
        /// 查询审批历史（轻量，不含当前节点）
        /// GET /api/processes/{businessId}/audit-history
        ///
        /// 适用场景：
        ///   - 只需要历史记录，不需要当前节点信息
        ///   - 业务系统判断审批结果（查最后一条 action）
        /// </summary>
        [HttpGet("{businessId}/audit-history")]
        public async Task<ActionResult<ApiResult<List<AuditRecordDto>>>> GetAuditHistory(
            string businessId)
        {
            var result = await _queryService.GetAuditHistoryAsync(
                new AuditHistoryRequest { BusinessId = businessId });
            return Ok(ApiResult<List<AuditRecordDto>>.Ok(result));
        }

        /// <summary>
        /// 按 businessId 查单条流程状态（极轻量）
        /// GET /api/processes/{businessId}/status
        ///
        /// 适用场景：
        ///   业务系统轮询流程是否完成时使用此接口
        ///   只返回 status / createdTime / completedTime，不查 Flowable 当前任务
        /// </summary>
        [HttpGet("{businessId}/status")]
        public async Task<ActionResult<ApiResult<ProcessListItemDto>>> GetStatus(
            string businessId)
        {
            var result = await _queryService.GetProcessStatusByBusinessIdAsync(businessId);
            return Ok(ApiResult<ProcessListItemDto>.Ok(result));
        }

        /// <summary>
        /// 分页查询流程列表
        /// GET /api/processes?businessType=xxx&amp;status=running&amp;pageIndex=1&amp;pageSize=20
        ///
        /// 过滤参数（均可选）：
        ///   businessType  : 按业务类型过滤
        ///   status        : running / completed / terminated / callback_failed
        ///   createdBy     : 按发起人工号过滤
        ///   createdTimeFrom / createdTimeTo : 时间范围（UTC ISO 格式）
        /// </summary>
        [HttpGet]
        public async Task<ActionResult<ApiResult<ProcessListResult>>> GetProcessList(
            [FromQuery] ProcessListRequest request)
        {
            var result = await _queryService.GetProcessListAsync(request);
            return Ok(ApiResult<ProcessListResult>.Ok(result));
        }
    }
}

