        public BpmnController(BpmnDeploymentAppService bpmnService)
        {
            _bpmnService = bpmnService;
        }

        /// <summary>
        /// 部署 BPMN 文件
        /// POST /api/flowable/bpmn/deploy
        ///
        /// Content-Type: multipart/form-data
        ///   file          : .bpmn 文件
        ///   slotConfigJson: 节点配置 JSON 字符串（见 slotConfig_v2.json）
        /// </summary>
        [HttpPost("deploy")]
        [Consumes("multipart/form-data")]
        public async Task<BpmnDeploymentResponse> Deploy(
            [FromForm] IFormFile file,
            [FromForm] string slotConfigJson,
            [FromForm] string deploymentRequestId = null,
            [FromForm] string businessVersion = null)
        {
            return await _bpmnService.DeployAsync(
                file,
                slotConfigJson,
                deploymentRequestId,
                businessVersion);
        }

        /// <summary>
        /// 查询流程定义节点语义（含驳回选项和 Slot 定义）
        /// GET /api/flowable/bpmn/{processDefinitionKey}/nodes
        /// </summary>
        [HttpGet("{processDefinitionKey}/nodes")]
        public async Task<List<ProcessDefinitionNodeDto>> GetNodes(
            string processDefinitionKey)
        {
            return await _bpmnService.GetProcessDefinitionNodesAsync(processDefinitionKey);
        }

        /// <summary>
        /// 删除部署
        /// DELETE /api/flowable/bpmn/deployments/{deploymentId}?cascade=true
        /// </summary>
        [HttpDelete("deployments/{deploymentId}")]
        public async Task<IActionResult> DeleteDeployment(
            string deploymentId,
            [FromQuery] bool cascade = true)
        {
            await _bpmnService.DeleteDeploymentAsync(deploymentId, cascade);
            return Ok(new { message = "部署删除成功" });
        }

        [HttpGet("deployments/status")]
        public Task<BpmnDeploymentStatusResponse> GetDeploymentStatus(
            [FromQuery] string processDefinitionKey,
            [FromQuery] string businessVersion)
            => _bpmnService.GetDeploymentStatusAsync(
                processDefinitionKey,
                businessVersion);
    }
}

using FlowableWrapper.Application.Services;
using FlowableWrapper.Domain.Reliability;
using Microsoft.AspNetCore.Mvc;

namespace FlowableWrapper.Api.Controllers;

[ApiController]
[Route("api/admin/workflow-migrations")]
public sealed class WorkflowMigrationAdminController : ControllerBase
{
    private readonly WorkflowMigrationAppService _migration;
    private readonly IWorkflowReliabilityStore _store;

    public WorkflowMigrationAdminController(
        WorkflowMigrationAppService migration,
        IWorkflowReliabilityStore store)
    {
        _migration = migration;
        _store = store;
    }

    [HttpGet("bindings/{businessId}")]
    public async Task<IActionResult> GetBinding(
        string businessId,
        CancellationToken cancellationToken)
    {
        var binding = await _store.GetBusinessByBusinessIdAsync(
            businessId,
            cancellationToken);
        return binding == null
            ? NotFound()
            : Ok(new
            {
                binding.BusinessId,
                binding.BusinessType,
                binding.ProcessInstanceId,
                binding.ProcessDefinitionKey,
                binding.ProcessDefinitionVersion,
                binding.FlowState,
                binding.CallbackState,
                binding.DataVersion,
                binding.UpdatedAt
            });
    }

    /// <summary>
    /// Idempotently migrates one ES page into DM8. Dry-run first, then process
    /// from the last page to the first to avoid page drift from new writes.
    /// </summary>
    [HttpPost("es-bindings")]
    public async Task<ActionResult<WorkflowBindingMigrationResult>>
        MigrateEsBindings(
            [FromQuery] int pageIndex = 1,
            [FromQuery] int pageSize = 100,
            [FromQuery] bool dryRun = true,
            CancellationToken cancellationToken = default)
    {
        return Ok(await _migration.MigrateEsBindingsPageAsync(
            pageIndex,
            pageSize,
            dryRun,
            cancellationToken));
    }
}

